package engine
import"testing"
func TestAirportBossNeedsObjectivesNotJustTurns(t *testing.T){bad:=EvaluateBossConversation("airport-crisis",[]string{"hello","hello again","thanks"});if bad.Complete{t.Fatal("three empty turns must not clear the boss")};good:=EvaluateBossConversation("airport-crisis",[]string{"I missed my flight this afternoon.","Could you rebook me on the earliest next flight?","Yes please, book it. Which gate should I use?"});if!good.Complete||good.Score!=100{t.Fatalf("expected complete airport mission, got %+v",good)}}
func TestConversationDistrictObjectives(t *testing.T){cafe:=EvaluateBossConversation("cafe-connection",[]string{"Hi, my name is Loc.","What about you, where are you from?","Nice to meet you. Would you like to talk again?"});if!cafe.Complete{t.Fatalf("cafe should complete: %+v",cafe)};plans:=EvaluateBossConversation("weekend-plans",[]string{"How about going to the cinema?","Let's meet at the cafe on Saturday.","Sounds good, see you there."});if!plans.Complete{t.Fatalf("plans should complete: %+v",plans)};repair:=EvaluateBossConversation("repair-misunderstanding",[]string{"Sorry, I didn't understand what you mean.","What I mean is that I can arrive later.","Got it, now I understand."});if!repair.Complete{t.Fatalf("repair should complete: %+v",repair)}}
func TestWorkDistrictObjectives(t *testing.T){standup:=EvaluateBossConversation("daily-standup",[]string{"Yesterday I finished the login fix.","Today I will add tests.","I have no blockers."});if!standup.Complete{t.Fatalf("standup should complete: %+v",standup)};req:=EvaluateBossConversation("requirement-clarity",[]string{"The requirement is unclear.","What exactly should happen for empty results?","So the requirement is to show suggestions when there are no results."});if!req.Complete{t.Fatalf("requirements should complete: %+v",req)};deadline:=EvaluateBossConversation("deadline-negotiation",[]string{"The Friday deadline creates a testing risk.","Cutting testing would hurt quality, so scope is the trade-off.","I propose a phased delivery: the MVP Friday and reporting next week."});if!deadline.Complete{t.Fatalf("deadline should complete: %+v",deadline)}}
